"""Sandbox Python startup hook, auto-imported by `site` via PYTHONPATH.

On Windows, os.mkdir(path, 0o700) makes CPython create the directory with
a protected owner-only security descriptor, which blocks ACL inheritance
and strips the AppContainer ACEs the sandbox relies on. tempfile.mkdtemp
and tempfile.TemporaryDirectory both do exactly that, so their directories
would be unusable inside the sandbox. This hook rewrites mode 0o700 to 0o777.
"""

import os

if os.name == "nt":
  _original_mkdir = os.mkdir

  def _mkdir(path, mode=0o777, *, dir_fd=None):
    """Like os.mkdir, but keeps mode-0o700 dirs accessible to the sandbox."""
    if mode == 0o700:
      mode = 0o777
    result = _original_mkdir(path, mode, dir_fd=dir_fd)
    # The venv module strips PYTHONPATH before running ensurepip under the
    # new interpreter, so that child never imports this hook. Copy the hook
    # into each new venv's site-packages, which `site` always imports from.
    try:
      if (
          dir_fd is None
          and os.path.basename(os.fspath(path)) == "site-packages"
      ):
        dst = os.path.join(os.fspath(path), "sitecustomize.py")
        if not os.path.exists(dst):
          with open(__file__, "r") as src:
            content = src.read()
          tmp_dst = f"{dst}.tmp.{os.getpid()}"
          with open(tmp_dst, "w") as out:
            out.write(content)
          os.replace(tmp_dst, dst)
    except OSError:
      pass
    return result

  os.mkdir = _mkdir

  # pip's build isolation replaces PYTHONPATH before spawning the build
  # backend, stripping this hook from that child. Whenever this process
  # overwrites PYTHONPATH, re-prepend the hook's directory. Prepending
  # matters: only the first sitecustomize.py on sys.path is imported,
  # and ours must win (it chains the shadowed one, see below).
  _hook_dir = os.path.dirname(os.path.abspath(__file__))
  _original_environ_setitem = os._Environ.__setitem__

  def _environ_setitem(self, key, value):
    try:
      if (
          isinstance(key, str)
          and key.upper() == "PYTHONPATH"
          and isinstance(value, str)
          and os.path.normcase(_hook_dir)
          not in map(os.path.normcase, value.split(os.pathsep))
      ):
        value = _hook_dir + os.pathsep + value if value else _hook_dir
    except Exception:  # pylint: disable=broad-except
      pass
    return _original_environ_setitem(self, key, value)

  os._Environ.__setitem__ = _environ_setitem

  # When this hook shadows another sitecustomize.py further down sys.path
  # (e.g. the one pip generates to expose isolated build dependencies),
  # `site` will not import it. Execute the shadowed module here so its
  # side effects still happen. Copies of this hook are skipped by marker.
  def _chain_shadowed_sitecustomize():
    import sys  # pylint: disable=g-import-not-at-top

    here = os.path.normcase(_hook_dir)
    for entry in sys.path:
      try:
        if not entry or os.path.normcase(os.path.abspath(entry)) == here:
          continue
        cand = os.path.join(entry, "sitecustomize.py")
        if not os.path.isfile(cand):
          continue
        with open(cand, "r") as f:
          src = f.read()
        if "_exebox_sitecustomize" in src:
          continue  # a copy of this hook (this line is the marker); already active
        namespace = {"__file__": cand, "__name__": "_shadowed_sitecustomize"}
        exec(compile(src, cand, "exec"), namespace)  # pylint: disable=exec-used
      except Exception:  # pylint: disable=broad-except
        pass
      else:
        break

  _chain_shadowed_sitecustomize()
